import{_ as a,o as r,c as t,a5 as o}from"./chunks/framework.CXvGqWf0.js";const f=JSON.parse('{"title":"漫画 · 第 50 话 首屏加载与白屏治理","description":"","frontmatter":{},"headers":[],"relativePath":"comics/perf/EP.50-first-screen-white-screen.md","filePath":"comics/perf/EP.50-first-screen-white-screen.md","lastUpdated":1793421609000}'),s={name:"comics/perf/EP.50-first-screen-white-screen.md"};function i(c,e,l,n,d,h){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="漫画-·-第-50-话-首屏加载与白屏治理" tabindex="-1">漫画 · 第 50 话 首屏加载与白屏治理 <a class="header-anchor" href="#漫画-·-第-50-话-首屏加载与白屏治理" aria-label="Permalink to &quot;漫画 · 第 50 话 首屏加载与白屏治理&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/perf/02-first-screen-white-screen">docs/perf/02-first-screen-white-screen.md</a> ｜ 原画：<a href="./EP.50-first-screen-white-screen.svg">EP.50-first-screen-white-screen.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。发布后盯着手机看，屏幕上只剩一个转圈的小光标，三秒后内容才突然出现。</li><li><strong>标签君</strong>：结构师，把关键渲染路径拆成四个方块，指出到底是谁挡住了首屏。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>用户点开页面，看到的是 3.2 秒纯白。像素酱原以为只是&quot;网络慢&quot;，标签君打开网络面板：首包 JS 3.2MB、12 个阻塞 CSS、字体 3 秒未到导致文字隐身。三个都跟首屏无关，却都排在首屏前面。标签君：先把关键路径让出来，再谈体验。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>三宗罪各有分工：巨包 JS 下载完还要解析编译，主线程被占满；多个 <code>link rel=&quot;stylesheet&quot;</code> 串行阻塞，浏览器必须等 CSSOM 才敢渲染；<code>font-display</code> 缺省时的 FOIT 会让文字在字体到达前完全不可见。共同结果就是白屏——不是&quot;加载慢&quot;，而是关键渲染路径被非关键资源占满。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>关键渲染路径是 HTML → CSSOM → 渲染树 → 首次绘制。图上 HTML 0.3s、CSS 1.2s、JS 2.4s，合计把 FCP 推到 3.9s。治理三招：① 骨架屏，用结构占位先给出视觉反馈，接口慢或失败都有兜底；② <code>font-display: swap</code>，先用系统字体渲染，字体到达再替换，配合 <code>size-adjust</code> 等度量匹配减少跳动；③ 资源提示，<code>preload</code> 关键 CSS/首屏图，<code>preconnect</code> 提前建连字体域，非关键资源 <code>defer</code>/<code>async</code> 或干脆挪到交互后。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>优化后时间线整段左移：HTML 0.2s、CSS 0.3s、首屏 JS 0.4s，FCP 从 3.9s 降到 1.1s，骨架首帧 0.6s、LCP 1.4s。注意最后一小段 IDLE 不是浪费，而是留给主线程喘息的余量。先看见结构，再看见内容，最后才是完整——这个顺序比总时长更重要。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>首屏只竞争关键资源：HTML、关键 CSS、首屏 JS，其余延后或按需加载。</li><li>骨架屏先给结构，慢接口与失败都要有兜底，白屏不能是终点。</li><li>字体三件套：<code>font-display: swap</code>、预加载、度量匹配，既要不挡字也要少跳动。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：把首屏 JS 从 3.2MB 压到 800KB 后，FCP 只从 3.9s 降到 3.5s，为什么收益这么小？</p><p><strong>答</strong>：说明瓶颈不在 JS 体积，而在关键路径的串行等待。常见原因：CSS 仍在阻塞、字体仍走 FOIT、JS 虽小但放在 <code>&lt;head&gt;</code> 同步执行、或首屏请求受 TCP/TLS 建连限制。应该用瀑布图看&quot;谁在等谁&quot;，先并行化与提前加载，再谈减体积；同时确认 FCP 的触发条件是否被骨架屏或占位图提前满足。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>白屏复现与治理对照（骨架屏 / font-display / preload）：<a href="./../../examples/perf/02-first-screen-white-screen">examples/perf/02-first-screen-white-screen</a></li><li>用 DevTools 网络节流跑同一页面，对比优化前后的 FCP 与 LCP 时间线。</li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>首屏出来了，滚动却开始卡顿。第 51 话《GPU 合成与渲染性能》——<code>left</code> 动画掉帧、60 张卡片 <code>will-change</code> 把显存撑爆，看渲染流水线怎么救。</p>',22)])])}const u=a(s,[["render",i]]);export{f as __pageData,u as default};
